html:
{% set order = generate_challan_list(doc)[2] %}
<style>td, th {
    border: 1px solid gray;
}
.center-cell{
text-align:center;
vertical-align:middle;

}
table {
    table-layout: fixed;
    width: 100%; /* Set the width of the table */
}

table td {
    word-wrap: break-word; /* Ensure long words wrap to the next line */
}
table .break-all{
word-break: break-all;
}
</style>

<table >
  <thead>
  <tr><th colspan="2" class="center-cell"><img width="100" height="100" src="{{doc.custom_qr_code_base}}"/></th>

      <th colspan="6" ><div>Academic Year: {{doc.custom_academic_year}}</div><div>Purchase Order No: {{doc.name}}</div><div>Date:{{frappe.utils.nowdate()}}</div>
<div>Required By: {{doc.schedule_date}}</div></th>
   
 
   
    </tr>
   
    <tr>
      <th>Item Group</th>
      <th>Item Code</th>
      <th>Quantity</th>
        <th colspan="2">Chapter</th>
        <th>Subject</th>
        <th>Class</th>
        <th>Product Url</th>
    </tr>
  </thead>
  
  <tbody> {% for item in order %}
  {% set item_details = frappe.get_doc("Item",item.item_code) %}
    <tr>
      <td>{{ item_details.item_group }} </td>
      <td>{{ item.item_code }}</td>
      <td>{{item.total_qty}}</td>
      <td colspan="2">{{item.chapter}}</td>
  <td>{{item.subject}}</td>
  <td>{{item_details.custom_class}}</td>
    <td class="break-all"><a href="{{item_details.custom_product_url}}">{{item_details.custom_product_url}}</a></td>
    </tr>
    {% endfor %}
    </tbody>
</table>
